import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, BoxGeometry, PlaneGeometry, PointLight } = THREE;

  const colors = config.intent?.visualSpec?.colors || {};
  const ink = colors.ink || '#16161d';
  const paper = colors.paper || '#e8ecf2';
  const accent = colors.accent || '#ff2a38';
  const surface = colors.surface || '#0b0b10';

  const root = new Group();
  root.name = 'home-gear-thumbnail';

  // lift layer — keeps adapter's scenePosition on `root` untouched
  const lift = new Group();
  root.add(lift);

  // --- Card body (machined metal panel) ---
  const cardW = 2.1, cardH = 1.35, cardD = 0.09;
  const cardGeo = new BoxGeometry(cardW, cardH, cardD);
  const cardMat = new MeshStandardNodeMaterial({
    color: surface, roughness: 0.5, metalness: 0.45
  });
  const card = new Mesh(cardGeo, cardMat);
  card.position.z = -0.045;
  lift.add(card);

  // --- Inset display well (ink-dark recess) ---
  const wellGeo = new BoxGeometry(cardW - 0.14, cardH - 0.14, 0.03);
  const wellMat = new MeshStandardNodeMaterial({
    color: ink, roughness: 0.62, metalness: 0.3
  });
  const well = new Mesh(wellGeo, wellMat);
  well.position.z = 0.005;
  lift.add(well);

  // --- Accent edge strip (left vertical, emissive red) ---
  const edgeGeo = new BoxGeometry(0.05, cardH, cardD + 0.02);
  const edgeMat = new MeshStandardNodeMaterial({
    color: accent, roughness: 0.4, metalness: 0.3,
    emissive: accent, emissiveIntensity: 1.4
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.set(-cardW / 2 + 0.03, 0, -0.045);
  lift.add(edge);

  // --- Thin paper keyline (faint inner border) ---
  const keyGeo = new BoxGeometry(cardW - 0.06, cardH - 0.06, cardD + 0.004);
  const keyMat = new MeshStandardNodeMaterial({
    color: ink, roughness: 0.55, metalness: 0.55
  });
  const keyline = new Mesh(keyGeo, keyMat);
  keyline.position.z = -0.042;
  lift.add(keyline);

  // --- Gear GLB mount ---
  const gearPivot = new Group();
  gearPivot.position.z = 0.09;
  lift.add(gearPivot);

  let gearRoot = null;
  ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
    const scene = gltf.scene || gltf;
    scene.traverse((c) => {
      if (c.isMesh && c.material) {
        if ('envMapIntensity' in c.material) c.material.envMapIntensity = 1.0;
      }
    });
    gearRoot = scene;
    gearPivot.add(scene);
    scene.scale.setScalar(0.001);
    gsap.to(scene.scale, {
      x: 0.55, y: 0.55, z: 0.55,
      duration: 0.8, ease: 'power3.out', delay: 0.2
    });
  }).catch(() => {});

  // --- Local accent + rim lights (scene already provides ambient 0.6 + key 1.2) ---
  const accentRim = new PointLight(accent, 0.7, 4, 2);
  accentRim.position.set(1.1, 0.7, 0.9);
  lift.add(accentRim);

  const paperRim = new PointLight(paper, 0.35, 4, 2);
  paperRim.position.set(-1.1, -0.5, 0.9);
  lift.add(paperRim);

  // --- Idle: one slow gear rotation (~0.2 rad/s) ---
  const idleTl = gsap.timeline({ repeat: -1, defaults: { ease: 'none' } });
  idleTl.to(gearPivot.rotation, { z: Math.PI * 2, duration: 31.4 });

  // --- Handlers ---
  const tweens = [];
  let pressTl = null;

  root.userData.handlers = {
    pointerenter: () => {
      tweens.push(
        gsap.to(lift.position, { y: 0.15, duration: 0.5, ease: 'power2.out', overwrite: 'auto' }),
        gsap.to(edgeMat, { emissiveIntensity: 2.1, duration: 0.4, ease: 'power2.out', overwrite: 'auto' })
      );
    },
    pointerleave: () => {
      tweens.push(
        gsap.to(lift.position, { y: 0, duration: 0.45, ease: 'power2.out', overwrite: 'auto' }),
        gsap.to(edgeMat, { emissiveIntensity: 1.4, duration: 0.4, ease: 'power2.out', overwrite: 'auto' })
      );
    },
    click: () => {
      if (pressTl) pressTl.kill();
      pressTl = gsap.timeline();
      pressTl
        .to(lift.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'power2.in' })
        .to(lift.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'back.out(2.2)' });
      ctx.emit('hub-home.select', { id: root.name });
    }
  };

  // --- Cleanup ---
  root.userData.cleanup = () => {
    idleTl.kill();
    if (pressTl) pressTl.kill();
    tweens.forEach((t) => t.kill());
    cardGeo.dispose(); cardMat.dispose();
    wellGeo.dispose(); wellMat.dispose();
    edgeGeo.dispose(); edgeMat.dispose();
    keyGeo.dispose(); keyMat.dispose();
    if (gearRoot) {
      gearRoot.traverse((c) => {
        if (c.isMesh) {
          c.geometry?.dispose?.();
          if (Array.isArray(c.material)) c.material.forEach((m) => m.dispose?.());
          else c.material?.dispose?.();
        }
      });
    }
  };

  return root;
}
